Interactive example

write_read_vanish &lt;- function(x) {

  tempfile &lt;- withr::local_tempfile(fileext = ".rds")

  saveRDS(x, file = tempfile)
  xnew &lt;- readRDS(tempfile)

  print(
    glue::glue("'{tempfile}' contained {xnew}.")
  )

  invisible(xnew)
}

